import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

public class SolutionTest {
    public static void main(String[] args) {
        assertEmpty(Solution.findPng(null, "icon.png"));

        Map<String, byte[]> catalog = new HashMap<String, byte[]>();
        byte[] original = new byte[]{1, 2, 3};
        catalog.put("icon.png", original);
        catalog.put("ICON.png", new byte[]{4});
        catalog.put("null.png", null);

        assertEmpty(Solution.findPng(catalog, null));
        assertEmpty(Solution.findPng(catalog, ""));
        assertEmpty(Solution.findPng(catalog, "   "));
        assertEmpty(Solution.findPng(catalog, " icon.png"));
        assertEmpty(Solution.findPng(catalog, "icon.png "));
        assertEmpty(Solution.findPng(catalog, "icon.PNG"));
        assertEmpty(Solution.findPng(catalog, "dir/icon.png"));
        assertEmpty(Solution.findPng(catalog, "dir\\icon.png"));
        assertEmpty(Solution.findPng(catalog, "missing.png"));
        assertEmpty(Solution.findPng(catalog, "null.png"));

        Optional<Solution.Asset> found = Solution.findPng(catalog, "icon.png");
        if (!found.isPresent()) throw new AssertionError("expected asset");
        Solution.Asset asset = found.get();
        assertEquals("image/png", asset.mediaType());
        assertArray(new byte[]{1, 2, 3}, asset.bytes());

        original[0] = 9;
        catalog.put("icon.png", new byte[]{8, 8});
        assertArray(new byte[]{1, 2, 3}, asset.bytes());

        byte[] exposed = asset.bytes();
        exposed[1] = 9;
        assertArray(new byte[]{1, 2, 3}, asset.bytes());
        if (asset.bytes() == asset.bytes()) throw new AssertionError("bytes() must return a fresh copy");

        assertEquals(3, catalog.size());
        assertArray(new byte[]{8, 8}, catalog.get("icon.png"));
        Optional<Solution.Asset> caseSensitive = Solution.findPng(catalog, "ICON.png");
        if (!caseSensitive.isPresent()) throw new AssertionError("exact uppercase basename should match");
        assertArray(new byte[]{4}, caseSensitive.get().bytes());
    }

    private static void assertEmpty(Optional<Solution.Asset> value) {
        if (value == null || value.isPresent()) throw new AssertionError("expected Optional.empty");
    }

    private static void assertArray(byte[] expected, byte[] actual) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError("expected " + Arrays.toString(expected) + " but got " + Arrays.toString(actual));
        }
    }

    private static void assertEquals(Object expected, Object actual) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError("expected " + expected + " but got " + actual);
        }
    }
}

